<?php $settings=array_column(App\Core\DB::all('SELECT setting_key,setting_value FROM school_settings WHERE school_id=?',[App\Core\Auth::schoolId()]),'setting_value','setting_key'); ?><section class="panel"><h2>School identity & finance settings</h2><?php startForm('settings.save'); foreach(['name'=>'School name','address'=>'Address','phone'=>'Phone','email'=>'Email','website'=>'Website','currency'=>'Currency code','invoice_prefix'=>'Invoice prefix','receipt_prefix'=>'Receipt prefix'] as $key=>$label) field($key,$label,$key==='email'?'email':'text',$school[$key]??'',in_array($key,['name','currency','invoice_prefix','receipt_prefix'],true)); selectField('current_year_id','Current academic year','academic_years',$settings['current_year_id']??'',false); selectField('current_term_id','Current term','terms',$settings['current_term_id']??'',false); endForm('Save settings'); ?><p class="note">Timezone: Africa/Dar_es_Salaam. Currency becomes fixed after the first invoice. Numbers retain their original prefixes after issue.</p></section><section class="panel"><h2>School logo</h2><?php if($school['logo_path']): ?><img class="school-logo" src="<?= e(url('image',['kind'=>'logo'])) ?>" alt="Current school logo"><?php endif ?><form method="post" enctype="multipart/form-data" class="stack"><?= csrf() ?><input type="hidden" name="action" value="image.upload"><input type="hidden" name="kind" value="logo"><label>PNG or JPEG · maximum 2 MB<input type="file" name="image" accept="image/png,image/jpeg" required></label><button class="button">Upload logo</button></form></section>
